  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "RU-505, the closest analogue sharing the pyrazolo[1,5-a]pyrimidine core and fluorophenyl/amide substitution, showed brain levels equal to or greater than blood over 24 h in mice, indicating high BBB permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Compound 4u, a primary benzamide with a CF3-substituted benzyl group, showed a brain/plasma ratio of 1.53–1.68 in mice, supporting good CNS access for amide-containing analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "The methylsulfone radiotracer [18F]1a showed substantial brain uptake, demonstrating that related CF3/fluorophenyl heteroaromatics can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "The sulfonamide analogue [18F]2a showed limited, slow BBB passage (SUV20min 0.48, brain-to-blood ratio 0.42), indicating that polar sulfonamide substitution can impair CNS access; however, this analogue is less similar to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: the closest structural analogue and multiple related amide/CF3 heteroaromatics show meaningful brain exposure, while the contradictory poor-penetration analogues are less similar and contain polar sulfonamide or anilide motifs not present in the query.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or efflux measurement for the exact query molecule.",
    "Primary amide efflux liability is not directly assessed in the available evidence.",
    "Human CNS exposure data are absent.",
    "Morgan similarity scores are moderate, so transfer from any single analogue is not definitive."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

